create schema if not exists private;
revoke all on schema private from public;
grant usage on schema private to authenticated;
create type public.member_role as enum ('org_admin','reception','student');
create table public.platform_admins(user_id uuid primary key references auth.users(id));
create table public.organizations(id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique check(slug ~ '^[a-z][a-z0-9-]{2,62}$'), active boolean not null default true, created_at timestamptz not null default now());
create table public.organization_settings(tenant_id uuid primary key references public.organizations(id), currency text not null default 'EUR' check(currency ~ '^[A-Z]{3}$'), languages text[] not null default '{sk,en,ru,uk}', primary_color text not null default '#142B4D' check(primary_color ~ '^#[0-9A-Fa-f]{6}$'), logo_url text, address text not null default '', reception_contact text not null default '', opening_hours text not null default '', due_day_start int not null default 1 check(due_day_start between 1 and 28), due_day_end int not null default 5 check(due_day_end between 1 and 28), privacy_text text not null default '', retention_days int not null default 1825 check(retention_days>0), features jsonb not null default '{"documents":true,"payments":true}', check(due_day_start<=due_day_end));
create table public.profiles(id uuid primary key references auth.users(id), display_name text not null default '', active boolean not null default true);
create table public.organization_memberships(id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.organizations(id), user_id uuid not null references public.profiles(id), role public.member_role not null, active boolean not null default true, unique(tenant_id,user_id));
create table public.rooms(id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.organizations(id), name text not null, category text not null, capacity int not null check(capacity>0), unique(tenant_id,id), unique(tenant_id,name));
create table public.residents(id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.organizations(id), user_id uuid not null references public.profiles(id), full_name text not null, email text not null, active boolean not null default true, unique(tenant_id,id), unique(tenant_id,user_id), foreign key(tenant_id,user_id) references public.organization_memberships(tenant_id,user_id));
create table public.tenancies(id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.organizations(id), resident_id uuid not null, room_id uuid not null, starts_on date not null, ends_on date not null, rent numeric(14,2) not null check(rent>=0), due_day int check(due_day between 1 and 28), unique(tenant_id,id), foreign key(tenant_id,resident_id) references public.residents(tenant_id,id), foreign key(tenant_id,room_id) references public.rooms(tenant_id,id), check(ends_on>=starts_on));
create table public.rent_charges(id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.organizations(id), resident_id uuid not null, period text not null, kind text not null default 'rent', amount numeric(14,2) not null check(amount>0), due_on date not null, created_at timestamptz not null default now(), unique(tenant_id,id), unique(tenant_id,resident_id,period,kind), foreign key(tenant_id,resident_id) references public.residents(tenant_id,id));
create table public.payments(id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.organizations(id), resident_id uuid not null, amount numeric(14,2) not null check(amount>0), received_on date not null, method text not null check(method in ('bank','cash','other')), reference text not null check(length(reference)>0), verified_by uuid not null references auth.users(id), created_at timestamptz not null default now(), unique(tenant_id,id), unique(tenant_id,reference), foreign key(tenant_id,resident_id) references public.residents(tenant_id,id));
create table public.payment_allocations(id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.organizations(id), payment_id uuid not null, charge_id uuid not null, amount numeric(14,2) not null check(amount>0), unique(payment_id,charge_id), foreign key(tenant_id,payment_id) references public.payments(tenant_id,id), foreign key(tenant_id,charge_id) references public.rent_charges(tenant_id,id));
create table public.payment_reversals(id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.organizations(id), payment_id uuid not null unique, reason text not null check(length(reason)>=5), created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), foreign key(tenant_id,payment_id) references public.payments(tenant_id,id));
create table public.installment_plans(id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.organizations(id), resident_id uuid not null, charge_id uuid not null unique, title text not null, approved_by uuid not null references auth.users(id), unique(tenant_id,id), foreign key(tenant_id,resident_id) references public.residents(tenant_id,id), foreign key(tenant_id,charge_id) references public.rent_charges(tenant_id,id));
create table public.installment_items(id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.organizations(id), plan_id uuid not null, amount numeric(14,2) not null check(amount>0), due_on date not null, foreign key(tenant_id,plan_id) references public.installment_plans(tenant_id,id));
create table public.documents(id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.organizations(id), resident_id uuid, title text not null, language text not null check(language in ('sk','en','ru','uk')), version int not null default 1 check(version>0), object_path text not null unique, uploaded_by uuid not null references auth.users(id), created_at timestamptz not null default now(), unique(tenant_id,id), foreign key(tenant_id,resident_id) references public.residents(tenant_id,id));
create table public.document_access(id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.organizations(id), document_id uuid not null, user_id uuid not null, foreign key(tenant_id,document_id) references public.documents(tenant_id,id), foreign key(tenant_id,user_id) references public.organization_memberships(tenant_id,user_id), unique(document_id,user_id));
create table public.announcements(id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.organizations(id), title text not null, body text not null, language text not null default 'sk', created_at timestamptz not null default now());
create table public.notifications(id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.organizations(id), user_id uuid not null, title text not null, body text not null, created_at timestamptz not null default now(), foreign key(tenant_id,user_id) references public.organization_memberships(tenant_id,user_id));
create table public.audit_logs(id bigint generated always as identity primary key, tenant_id uuid references public.organizations(id), actor_id uuid, action text not null, entity text not null, entity_id text, created_at timestamptz not null default now());
create table public.organization_domains(id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.organizations(id), hostname text not null unique, verified_at timestamptz);
create table public.support_grants(id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.organizations(id), platform_user_id uuid not null references public.platform_admins(user_id), expires_at timestamptz not null, authorized_by uuid not null references auth.users(id), reason text not null);
-- Support grants are records only: they deliberately do NOT bypass content RLS.
create or replace function private.is_platform() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.platform_admins a join public.profiles p on p.id=a.user_id where a.user_id=auth.uid() and p.active and exists(select 1 from auth.sessions s where s.id=(auth.jwt()->>'session_id')::uuid and s.user_id=auth.uid()))$$;
create or replace function private.has_role(t uuid, roles public.member_role[] default array['org_admin','reception','student']::public.member_role[]) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.organization_memberships m join public.organizations o on o.id=m.tenant_id join public.profiles p on p.id=m.user_id where m.tenant_id=t and m.user_id=auth.uid() and m.active and p.active and o.active and m.role=any(roles) and exists(select 1 from auth.sessions s where s.id=(auth.jwt()->>'session_id')::uuid and s.user_id=auth.uid()))$$;
create or replace function private.own_resident(t uuid,r uuid) returns boolean language sql stable security definer set search_path='' as $$select private.has_role(t) and exists(select 1 from public.residents where tenant_id=t and id=r and user_id=auth.uid() and active)$$;
create or replace function private.can_document(d uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.documents where id=d and private.has_role(tenant_id) and (private.has_role(tenant_id,array['org_admin','reception']::public.member_role[]) or resident_id is null or private.own_resident(tenant_id,resident_id) or exists(select 1 from public.document_access a where a.document_id=d and a.user_id=auth.uid())))$$;
revoke all on all functions in schema private from public;
grant execute on all functions in schema private to authenticated;
