create policy platform_self on public.platform_admins for select to authenticated using(user_id=auth.uid() and private.is_platform());
create policy profile_read on public.profiles for select to authenticated using(id=auth.uid() and active);
create policy organization_read on public.organizations for select to authenticated using(private.has_role(id) or private.is_platform());
create policy organization_platform on public.organizations for all to authenticated using(private.is_platform()) with check(private.is_platform());
create policy memberships_read on public.organization_memberships for select to authenticated using(private.has_role(tenant_id) and (user_id=auth.uid() or private.has_role(tenant_id,array['org_admin']::public.member_role[])));
create policy settings_read on public.organization_settings for select to authenticated using(private.has_role(tenant_id) or private.is_platform());
create policy settings_update on public.organization_settings for update to authenticated using(private.has_role(tenant_id,array['org_admin']::public.member_role[])) with check(private.has_role(tenant_id,array['org_admin']::public.member_role[]));
grant update on public.organization_settings to authenticated;
grant insert,update on public.organizations to authenticated;
