create policy read_installment_plans on public.installment_plans for select to authenticated using(private.has_role(tenant_id,array['org_admin','reception']::public.member_role[]) or private.own_resident(tenant_id,resident_id));
create policy read_allocations on public.payment_allocations for select to authenticated using(exists(select 1 from public.payments p where p.id=payment_id));
create policy read_reversals on public.payment_reversals for select to authenticated using(exists(select 1 from public.payments p where p.id=payment_id));
create policy read_items on public.installment_items for select to authenticated using(exists(select 1 from public.installment_plans p where p.id=plan_id));
create policy read_documents on public.documents for select to authenticated using(private.can_document(id));
create policy read_access on public.document_access for select to authenticated using(private.has_role(tenant_id,array['org_admin','reception']::public.member_role[]) or (user_id=auth.uid() and private.has_role(tenant_id)));
create policy read_notifications on public.notifications for select to authenticated using(user_id=auth.uid() and private.has_role(tenant_id));
create policy read_audit on public.audit_logs for select to authenticated using(private.has_role(tenant_id,array['org_admin']::public.member_role[]) or (tenant_id is null and private.is_platform()));
create policy read_domains on public.organization_domains for select to authenticated using(private.is_platform());
create policy read_support on public.support_grants for select to authenticated using(private.is_platform() or private.has_role(tenant_id,array['org_admin']::public.member_role[]));
