create or replace function private.audit_write() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.audit_logs(tenant_id,actor_id,action,entity,entity_id) values((to_jsonb(new)->>'tenant_id')::uuid,auth.uid(),tg_op,tg_table_name,to_jsonb(new)->>'id'); return new; end$$;
revoke all on function private.audit_write() from public;
