insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('residence-private','residence-private',false,10485760,array['application/pdf','image/png','image/jpeg']);
create policy download_document on storage.objects for select to authenticated using(bucket_id='residence-private' and exists(select 1 from public.documents d where d.object_path=name and private.can_document(d.id)));
create policy upload_document on storage.objects for insert to authenticated with check(bucket_id='residence-private' and exists(select 1 from public.documents d where d.object_path=name and d.uploaded_by=auth.uid() and private.has_role(d.tenant_id,array['org_admin','reception']::public.member_role[])));
-- Exact metadata-to-path binding prevents path-based tenant guessing.
create or replace function private.validate_document() returns trigger language plpgsql set search_path='' as $$begin if new.uploaded_by<>auth.uid() or new.object_path<>new.tenant_id::text||'/'||new.id::text then raise exception 'Invalid document ownership/path'; end if; return new; end$$;
create trigger validate_document before insert on public.documents for each row execute function private.validate_document();
revoke all on function private.validate_document() from public;
create function private.create_organization(p_name text,p_slug text) returns uuid language plpgsql security definer set search_path='' as $$declare t uuid;begin
if not private.is_platform() then raise exception 'Forbidden' using errcode='42501'; end if;
insert into public.organizations(name,slug) values(p_name,p_slug) returning id into t;
insert into public.organization_settings(tenant_id) values(t); return t;end$$;
create function public.create_organization(p_name text,p_slug text) returns uuid language sql security invoker set search_path='' as $$select private.create_organization(p_name,p_slug)$$;
create function private.set_membership(p_tenant uuid,p_user uuid,p_role public.member_role,p_active boolean) returns void language plpgsql security definer set search_path='' as $$begin
if not (private.has_role(p_tenant,array['org_admin']::public.member_role[]) or (private.is_platform() and p_role='org_admin')) then raise exception 'Forbidden' using errcode='42501';end if;
if p_user=auth.uid() then raise exception 'Cannot change own membership';end if;
insert into public.organization_memberships(tenant_id,user_id,role,active) values(p_tenant,p_user,p_role,p_active) on conflict(tenant_id,user_id) do update set role=excluded.role,active=excluded.active;
end$$;
create function public.set_membership(p_tenant uuid,p_user uuid,p_role public.member_role,p_active boolean) returns void language sql security invoker set search_path='' as $$select private.set_membership(p_tenant,p_user,p_role,p_active)$$;
create function private.issue_charge(p_tenant uuid,p_resident uuid,p_period text,p_amount numeric,p_due date) returns uuid language plpgsql security definer set search_path='' as $$declare c uuid;begin
if not private.has_role(p_tenant,array['org_admin','reception']::public.member_role[]) then raise exception 'Forbidden' using errcode='42501';end if;
if p_amount<>round(p_amount,2) then raise exception 'Invalid precision';end if;
insert into public.rent_charges(tenant_id,resident_id,period,amount,due_on) values(p_tenant,p_resident,p_period,p_amount,p_due) returning id into c;return c;end$$;
create function public.issue_charge(p_tenant uuid,p_resident uuid,p_period text,p_amount numeric,p_due date) returns uuid language sql security invoker set search_path='' as $$select private.issue_charge(p_tenant,p_resident,p_period,p_amount,p_due)$$;
create function private.record_payment(p_tenant uuid,p_resident uuid,p_amount numeric,p_received date,p_method text,p_reference text,p_allocations jsonb) returns uuid language plpgsql security definer set search_path='' as $$declare pid uuid; a jsonb;c public.rent_charges;used numeric;total numeric:=0;v numeric;begin
if not private.has_role(p_tenant,array['org_admin','reception']::public.member_role[]) then raise exception 'Forbidden' using errcode='42501';end if;
if p_amount<>round(p_amount,2) or jsonb_typeof(p_allocations)<>'array' then raise exception 'Invalid payment';end if;
-- Serialize all ledger operations for this resident. This also prevents concurrent over-allocation.
perform 1 from public.residents where tenant_id=p_tenant and id=p_resident for update;
insert into public.payments(tenant_id,resident_id,amount,received_on,method,reference,verified_by) values(p_tenant,p_resident,p_amount,p_received,p_method,p_reference,auth.uid()) returning id into pid;
for a in select value from jsonb_array_elements(p_allocations) loop
v:=(a->>'amount')::numeric;if v<>round(v,2) or v<=0 then raise exception 'Invalid allocation';end if;
select * into strict c from public.rent_charges where tenant_id=p_tenant and id=(a->>'charge_id')::uuid and resident_id=p_resident for update;
select coalesce(sum(pa.amount),0) into used from public.payment_allocations pa where pa.charge_id=c.id and not exists(select 1 from public.payment_reversals r where r.payment_id=pa.payment_id);
if used+v>c.amount then raise exception 'Charge over-allocation';end if;
total:=total+v;insert into public.payment_allocations(tenant_id,payment_id,charge_id,amount) values(p_tenant,pid,c.id,v);
end loop;
if total>p_amount then raise exception 'Payment over-allocation';end if;
insert into public.notifications(tenant_id,user_id,title,body) select p_tenant,user_id,'payment_received',p_amount::text from public.residents where id=p_resident and tenant_id=p_tenant;
return pid;end$$;
create function public.record_payment(p_tenant uuid,p_resident uuid,p_amount numeric,p_received date,p_method text,p_reference text,p_allocations jsonb) returns uuid language sql security invoker set search_path='' as $$select private.record_payment(p_tenant,p_resident,p_amount,p_received,p_method,p_reference,p_allocations)$$;
create function private.reverse_payment(p_tenant uuid,p_payment uuid,p_reason text) returns void language plpgsql security definer set search_path='' as $$declare r uuid;begin
if not private.has_role(p_tenant,array['org_admin']::public.member_role[]) then raise exception 'Forbidden' using errcode='42501';end if;
select resident_id into strict r from public.payments where tenant_id=p_tenant and id=p_payment;
perform 1 from public.residents where tenant_id=p_tenant and id=r for update;
insert into public.payment_reversals(tenant_id,payment_id,reason,created_by) values(p_tenant,p_payment,p_reason,auth.uid());end$$;
create function public.reverse_payment(p_tenant uuid,p_payment uuid,p_reason text) returns void language sql security invoker set search_path='' as $$select private.reverse_payment(p_tenant,p_payment,p_reason)$$;
create function private.create_plan(p_tenant uuid,p_charge uuid,p_title text,p_items jsonb) returns uuid language plpgsql security definer set search_path='' as $$declare c public.rent_charges;pid uuid;a jsonb;s numeric:=0;v numeric;begin
if not private.has_role(p_tenant,array['org_admin']::public.member_role[]) then raise exception 'Forbidden' using errcode='42501';end if;
select * into strict c from public.rent_charges where id=p_charge and tenant_id=p_tenant for update;
insert into public.installment_plans(tenant_id,resident_id,charge_id,title,approved_by) values(p_tenant,c.resident_id,c.id,p_title,auth.uid()) returning id into pid;
for a in select value from jsonb_array_elements(p_items) loop
v:=(a->>'amount')::numeric;if v<>round(v,2) then raise exception 'Invalid precision';end if;
s:=s+v;insert into public.installment_items(tenant_id,plan_id,amount,due_on) values(p_tenant,pid,v,(a->>'due_on')::date);end loop;
if s<>c.amount then raise exception 'Installments must equal charge';end if;return pid;end$$;
create function public.create_plan(p_tenant uuid,p_charge uuid,p_title text,p_items jsonb) returns uuid language sql security invoker set search_path='' as $$select private.create_plan(p_tenant,p_charge,p_title,p_items)$$;
-- Never expose definer functions directly through PostgREST.
revoke all on all functions in schema private from public,anon;
grant execute on all functions in schema private to authenticated;
revoke all on function public.create_organization(text,text),public.set_membership(uuid,uuid,public.member_role,boolean),public.issue_charge(uuid,uuid,text,numeric,date),public.record_payment(uuid,uuid,numeric,date,text,text,jsonb),public.reverse_payment(uuid,uuid,text),public.create_plan(uuid,uuid,text,jsonb) from public,anon;
grant execute on function public.create_organization(text,text),public.set_membership(uuid,uuid,public.member_role,boolean),public.issue_charge(uuid,uuid,text,numeric,date),public.record_payment(uuid,uuid,numeric,date,text,text,jsonb),public.reverse_payment(uuid,uuid,text),public.create_plan(uuid,uuid,text,jsonb) to authenticated;
-- Auth creates only a profile, never an organization membership or privileged role.
create function private.new_user() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.profiles(id) values(new.id);return new;end$$;
revoke all on function private.new_user() from public,anon,authenticated;
create trigger residence_profile after insert on auth.users for each row execute function private.new_user();
